INSERT INTO `product` VALUES (1,'Mô hình SDBB SD Zaku Series Set','Bandai',600000,462000,510000,50,1,'2025-03-21 23:47:58','2025-05-15 21:46:42',1,8,'<p><strong style=\"background-color: rgb(62, 62, 62); color: rgb(255, 255, 255);\" class=\"ql-size-large\"> 1. Tổng quan về mô hình SD Zaku Series Set </strong></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Tên sản phẩm: Mô hình SDBB SD Zaku Series Set</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Series phim: Mobile Suit Gundam SEED DESTINY</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Phân loại: Mô hình SD (Super Deformed)</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Tỉ lệ: NON SCALE</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Nhà sản xuất: BANDAI SPRITS CO., LTĐ</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Xuất xứ: Nhật Bản</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Năm sản xuất: 2024</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Nhà nhập khẩu và phân phối: Công ty TNHH Giải trí Gogo</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Thành phần: Nhựa PS</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Tuổi sử dụng: Từ 8 tuổi trở lên</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Chiều cao khi hoàn thành: 10&nbsp;cm</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Mô hình chưa được lắp ráp, bạn cần lắp theo sách hướng dẫn</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Là mô hình có khả năng thay đổi nhiều tư thế. Dùng để trưng bày hoặc pose dáng chụp ảnh</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Mô hình được lắp theo kiểu bấm khớp, không phải dùng keo dán</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Không có base đi kèm</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Kích thước, cân nặng hộp: 31 x 20 x 13 cm / 640g</span></p><p><strong style=\"background-color: rgb(62, 62, 62); color: rgb(255, 255, 255);\" class=\"ql-size-large\"> 2. Chi tiết về mô hình SD Zaku Series Set </strong></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">Bộ mô hình bao gồm:</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- BB Senshi 281 Gunner Zaku Warrior (Lunamaria Hawke\'s exclusive machine) x 1</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- BB Senshi 285 Blaze Zaku Phantom (Rey the Barrel\'s exclusive machine) x 1</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- BB Senshi 296 Blaze Zaku Warrior x 1</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- BB Senshi 298 Blaze Zaku Phantom (Heine Westenfluss\'s exclusive machine) x 1</span></p><p class=\"ql-indent-1\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(33, 37, 41);\">- Sticker x 4</span></p>',0,'Còn hàng'),(2,'Mô hình SDCS 21 SD Mighty Strike Freedom Gundam','Banda