DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `user_id` int NOT NULL AUTO_INCREMENT,
  `user_name` varchar(50) NOT NULL,
  `user_pass` varchar(255) NOT NULL,
  `user_fullname` varchar(100) DEFAULT NULL,
  `user_gender` varchar(45) DEFAULT NULL,
  `user_birthday` varchar(50) DEFAULT NULL,
  `user_mobilephone` varchar(15) DEFAULT NULL,
  `user_email` varchar(100) DEFAULT NULL,
  `user_address` text,
  `user_roles` int DEFAULT NULL,
  `user_created_date` datetime DEFAULT CURRENT_TIMESTAMP,
  `user_last_modified` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `user_deleted` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `user_name` (`user_name`),
  UNIQUE KEY `user_email` (`user_email`),
  KEY `user_roles` (`user_roles`),
  CONSTRAINT `user_ibfk_1` FOREIGN KEY (`user_roles`) REFERENCES `roles` (`role_id`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
